func TestAnArtifactAndAnImageAndABoxOnlyPath(emonT *testing.T) {
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var m int32 = evidence.MkNew(mk, 1, 1, 0, 0, -1, 0)
	var r int32 = gtPath(pa, evidence.PaRect(), evidence.PgFilled(), 0, -1, 0, 0, 4950, 20000, 5050)
	evidence.MkSet(mk, m, 6, 1)
	evidence.PaSet(pa, r, evidence.PfMark(), m)
	port.AssertEq(emonT, gtRun(pa, pts, mk, im, gvec.GvSegments(), out), 1, "a path with no geometry is read by its box")
	port.AssertEq(emonT, gtC(out, 0, 15)&glayer.GqArtifactPagination(), glayer.GqArtifactPagination(), "an /Artifact /Pagination mark is flagged")
	port.AssertEq(emonT, gtC(out, 0, 2), -1, "a box-only candidate has no point")
	// a thin visible image placement is a rule of colour -1; a hidden one is nothing
	port.CellsDrop(pa, 0)
	var i int32 = evidence.ImNew(im, 1, 0, 0, 20000, 100, 5, 1, 1)
	port.AssertEq(emonT, gtRun(pa, pts, mk, im, gvec.GvSegments(), out), 1, "an image rule")
	port.AssertEq(emonT, gtC(out, 0, 13), -1, "of unknown colour")
	port.AssertEq(emonT, gtC(out, 0, 15), glayer.GqFromImage(), "flagged from-image")
	port.AssertEq(emonT, gtRun(pa, pts, mk, im, gvec.GvLegacy(), out), 0, "legacy has no image rules")
	evidence.ImSet(im, i, evidence.MfVis(), 5)
	port.AssertEq(emonT, gtRun(pa, pts, mk, im, gvec.GvSegments(), out), 0, "a hidden image is not one")
}
